// TypeScript Version: 4.1

/**
* Method for determining how a size calculation should be performed.
*/
type ContainsMethod = 'content' | 'padding';

/**
* Autosize method.
*/
type AutosizeMethod = 'pad' | 'fit' | 'fit-x' | 'fit-y' | 'none';

/**
* Interface describing constructor options.
*/
interface Options {
	/**
	* Method for determining how a size calculation should be performed. Default: 'content'.
	*/
	contains?: ContainsMethod;

	/**
	* Boolean indicating whether to re-calculate an autosize layout on every view update. Default: false.
	*/
	resize?: boolean;

	/**
	* Autosize method. Default: 'pad'.
	*/
	type?: AutosizeMethod;
}

/**
* Interface describing a JSON-serialized autosize instance.
*/
interface JSON {
	/**
	* Method for determining how a size calculation should be performed.
	*/
	contains: ContainsMethod;

	/**
	* Boolean indicating whether to re-calculate an autosize layout on every view update.
	*/
	resize: boolean;

	/**
	* Autosize type.
	*/
	type: AutosizeMethod;
}

/**
* Interface describing an autosize instance.
*/
interface Autosize {
	/**
	* Method for determining how a size calculation should be performed.
	*
	* @example
	* var autosize = new Autosize();
	*
	* autosize.contains = 'padding';
	*
	* var v = autosize.contains;
	* // returns 'padding'
	*/
	contains: ContainsMethod;

	/**
	* List of enumerable properties.
	*
	* @example
	* var autosize = new Autosize();
	*
	* var v = autosize.properties;
	* // returns [ 'contains', 'resize', 'type' ]
	*/
	readonly properties: Array<string>;

	/**
	* Boolean indicating whether to re-calculate an autosize layout on every view update.
	*
	* @example
	* var autosize = new Autosize();
	*
	* autosize.resize = true;
	*
	* var v = autosize.resize;
	* // returns true
	*/
	resize: boolean;

	/**
	* Autosize type.
	*
	* @example
	* var autosize = new Autosize();
	*
	* autosize.type = 'none';
	*
	* var v = autosize.type;
	* // returns 'none'
	*/
	type: AutosizeMethod;

	/**
	* Serializes an autosize instance to a JSON object.
	*
	* ## Notes
	*
	* -   This method is implicitly invoked by `JSON.stringify`.
	*
	* @returns JSON object
	*
	* @example
	* var autosize = new Autosize({
	*     'type': 'fit'
	* });
	*
	* var v = autosize.toJSON();
	* // returns { 'contains': 'content', 'resize': false, 'type': 'fit' }
	*/
	toJSON(): JSON;
}

/**
* Interface defining an autosize constructor which is both "newable" and "callable".
*/
interface Constructor {
	/**
	* Autosize constructor.
	*
	* @param options - constructor options
	* @param options.contains - method for determining how a size calculation should be performed (default: 'content')
	* @param options.resize - boolean indicating whether to re-calculate an autosize layout on every view update (default: false)
	* @param options.type - autosize method (default: 'pad')
	* @throws options argument must be an object
	* @throws must provide valid options
	* @returns autosize instance
	*
	* @example
	* var autosize = new Autosize({
	*     'type': 'fit'
	* });
	*
	* var v = autosize.type;
	* // returns 'fit'
	*/
	new ( options?: Options ): Autosize;

	/**
	* Autosize constructor.
	*
	* @param options - constructor options
	* @param options.contains - method for determining how a size calculation should be performed (default: 'content')
	* @param options.resize - boolean indicating whether to re-calculate an autosize layout on every view update (default: false)
	* @param options.type - autosize method (default: 'pad')
	* @throws options argument must be an object
	* @throws must provide valid options
	* @returns autosize instance
	*
	* @example
	* var autosize = Autosize({
	*     'type': 'fit'
	* });
	*
	* var v = autosize.type;
	* // returns 'fit'
	*/
	( options?: Options ): Autosize;
}

/**
* Autosize constructor.
*
* @param options - constructor options
* @param options.contains - method for determining how a size calculation should be performed (default: 'content')
* @param options.resize - boolean indicating whether to re-calculate an autosize layout on every view update (default: false)
* @param options.type - autosize method (default: 'pad')
* @throws options argument must be an object
* @throws must provide valid options
* @returns autosize instance
*
* @example
* var autosize = new Autosize();
* // returns <Autosize>
*
* var v = autosize.toJSON();
* // returns { 'contains': 'content', 'resize': false, 'type': 'pad' }
*/
declare var ctor: Constructor;


// EXPORTS //

export = ctor;

// eslint-doctest-alias: Autosize
